// Generate app/generated/upgrade.json from the docs/UPGRADE-*.md migration
// guides so they're rendered on the docs site (ui.kungal.com/upgrade) — not just
// buried in the repo. These guides change rarely (only on breaking majors), so
// the JSON is committed and regenerated by hand (`pnpm gen:upgrade`) when edited.
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { marked } from 'marked'

const here = dirname(fileURLToPath(import.meta.url))
const DOCS = join(here, '../../../docs')
const OUT = join(here, '../app/generated/upgrade.json')

// Order matters: the 1.x guide is the common case, the breaking 0.5.2→1.0 guide
// is for stragglers. `slug` doubles as the in-page anchor id.
const GUIDES = [
  { slug: 'v1x', file: 'UPGRADE-1.x.md' },
  { slug: 'v052-to-100', file: 'UPGRADE-0.5.2-to-1.0.0.md' },
]

const out = GUIDES.map(({ slug, file }) => {
  const lines = readFileSync(join(DOCS, file), 'utf8').split('\n')
  const titleIdx = lines.findIndex((l) => /^#\s+/.test(l))
  const title = titleIdx >= 0 ? lines[titleIdx].replace(/^#\s+/, '').trim() : file
  const body = lines
    .slice(titleIdx >= 0 ? titleIdx + 1 : 0)
    .join('\n')
    .trim()

  // Point the cross-links between guides at the in-page anchors on this route.
  const html = marked
    .parse(body)
    .replace(/href="\.\/UPGRADE-1\.x\.md[^"]*"/g, 'href="#v1x"')
    .replace(/href="\.\/UPGRADE-0\.5\.2-to-1\.0\.0\.md[^"]*"/g, 'href="#v052-to-100"')

  return { slug, title, html }
})

writeFileSync(OUT, JSON.stringify(out, null, 2) + '\n')
console.log(`wrote upgrade.json — ${out.length} guides`)
